        "Hard & Soft Skills"
      ]
    },
    "portfolio_module": {
      "source": "Behance",
      "display_method": "Galeria integrada ou referenciamento externo com deep links",
      "goal": "Exibição de Projetos Pessoais com foco visual"
    },
    "connectivity_hub": {
      "type": "Seção de Contato/Rodapé",
      "platforms": [
        "LinkedIn",
        "WhatsApp",
        "Instagram"
      ],
      "requirement": "Links funcionais e CTAs (Call to Actions) proeminentes"
    }
  },
  "deliverables": {
    "primary_output": "Especificação Técnica Detalhada",
    "format_options": [
      "Wireframe Lógico (Descrição Textual da UX)",
      "Código Base Estrutural (HTML5 Semântico + CSS Grid/Flexbox)"
    ]
  },
  "instruction_script": "Como um especialista em Design de  Digital, desenvolva a estrutura completa para um website de portfólio de página única. Utilize a paleta preto e branco para criar uma estética sofisticada. Estruture o site de acordo com portfólio anexdo. A saída deve priorizar a arquitetura da informação, garantindo que o currículo, o portfólio do Behance e os links sociais sejam integrados de forma fluida e responsiva."
}


